<script lang="ts">
 import {notify} from './notifications.svelte'
 import {untrack} from 'svelte'
 import {Radio,Rss,Bot,Pause,Play,Plus,ArrowUpRight,RefreshCw,BookOpen,CheckCircle2} from '@lucide/svelte'
 import {request,relativeDate,type Auth,type Community} from './api'
 import {Button} from '$lib/components/ui/button/index.js'
 import {Input} from '$lib/components/ui/input/index.js'
 import ContentSkeleton from './ContentSkeleton.svelte'
 type Room=Community&{sourceCount:number;knowledgeCount:number;pendingJobs:number}
 type Source={id:string;title:string;url:string;rights:string;state:string;revision:number;last_success:number|null;last_error:string|null;mode:string}
 type Item={id:string;title:string;url:string;summary:string;state:string;revision:number;evidence:{title:string}[]}
 type Entry={agent_id:string;family:string;role:string;revoked:number;actor:{name:string};community:{id:string};mandates:{id:string;purpose:string;expires:number;revoked:number}[];editorial:{id:string;purpose:string;expires:number;revoked:number}[]}
 type Config={community_id:string;agent_id:string;revision:number;enabled:number;daily_limit:number;interval_minutes:number;posting_mandate_id:string|null;editorial_mandate_id:string|null}
 type ResidentState={config:Config|null;ready:boolean;reason:string|null;provider:string}
 type Job={id:string;skill:string;state:string;created:number;error:string|null;model:string|null;result_kind:string|null;result_id:string|null}
 let {auth}:{auth:Auth}=$props()
 let rooms=$state<Room[]>([]),scope=$state(''),loading=$state(true),busy=$state(false),error=$state(''),section=$state('sources'),sources=$state<Source[]>([]),items=$state<Item[]>([]),entries=$state<Entry[]>([]),jobs=$state<Job[]>([]),resident=$state<ResidentState|null>(null)
 let sourceForm=$state(false),title=$state(''),url=$state(''),sourceKind=$state('news'),mode=$state('review'),rights=$state('link-only'),agentId=$state(''),postingId=$state(''),editorialId=$state(''),dailyLimit=$state('3'),intervalMinutes=$state('360'),skill=$state('knowledge-draft'),provider=$state(''),acquisition=$state(false)
 const eligible=$derived(entries.filter(e=>e.community.id===scope&&e.family==='aksara'&&e.role!=='guest'&&!e.revoked)),selectedAgent=$derived(eligible.find(e=>e.agent_id===agentId))
 const jobLabels:Record<string,string>={queued:'Menunggu',running:'Sedang bekerja',succeeded:'Selesai',abstained:'Tidak dilanjutkan',failed:'Belum berhasil',cancelled:'Dihentikan'}
 const skillLabels:Record<string,string>={'knowledge-draft':'Catatan pengetahuan','source-digest':'Ringkasan sumber','research-question':'Pertanyaan untuk komunitas'}
 let generation=0
 async function load(){const mine=++generation;loading=true;error=''
  try{const info=await request<{communities:Room[];residentProvider:string;acquisitionConfigured:boolean}>('/v1/studio');if(mine!==generation)return;rooms=info.communities;provider=info.residentProvider;acquisition=info.acquisitionConfigured;scope=rooms.some(r=>r.id===scope)?scope:rooms.find(r=>r.visibility==='public')?.id??'';await loadScope(scope,mine)}catch(e){error=e instanceof Error?e.message:'Studio belum dapat dimuat.'}finally{if(mine===generation)loading=false}}
 async function loadScope(id:string,mine=++generation){error='';resident=null;sources=[];items=[];jobs=[];entries=[]
  if(!id)return
  try{const [ss,is,rs,js,as]=await Promise.all([request<Source[]>('/v1/discovery/sources?community='+id),request<Item[]>('/v1/discovery/items?review=true&community='+id),request<ResidentState>('/v1/resident/config?community='+id),request<Job[]>('/v1/resident/jobs?community='+id),request<Entry[]>('/v1/agents')]);if(mine!==generation)return;sources=ss;items=is;resident=rs;jobs=js;entries=as;agentId=rs?.config?.agent_id??as.find(a=>a.community.id===id&&a.family==='aksara')?.agent_id??'';postingId=rs?.config?.posting_mandate_id??'';editorialId=rs?.config?.editorial_mandate_id??'';dailyLimit=String(rs?.config?.daily_limit??3);intervalMinutes=String(rs?.config?.interval_minutes??360)}catch(e){if(mine===generation)error=e instanceof Error?e.message:'Data komunitas belum tersedia.'}}
 $effect(()=>{void auth.actor?.id;untrack(()=>{if(auth.actor)void load();else loading=false});return()=>{generation++}})
 async function act(fn:()=>Promise<void>){if(busy)return;busy=true;error='';try{await fn();await loadScope(scope)}catch(e){error=e instanceof Error?e.message:'Permintaan belum berhasil.'}finally{busy=false}}
 async function saveSource(){await act(async()=>{await request('/v1/discovery/sources',{communityId:scope,title,url,kind:sourceKind,mode,rights,language:'id',requestKey:crypto.randomUUID()});sourceForm=false;title='';url='';notify('Sumber ditambahkan. Periksa contoh sebelum menerbitkan.')})}
 async function configure(enabled:boolean){await act(async()=>{await request('/v1/resident/config',{communityId:scope,agentId,postingMandateId:postingId||null,editorialMandateId:editorialId||null,enabled,dailyLimit:Number(dailyLimit),intervalMinutes:Number(intervalMinutes),revision:resident?.config?.revision??0,requestKey:crypto.randomUUID()});notify(enabled?'Penghuni diaktifkan.':'Penghuni dijeda.')})}
</script>
{#if !auth.actor}<section class="strata-nodata"><Radio size={28}/><h1>Studio komunitas</h1><Button href="/login">Masuk</Button></section>
{:else if loading}<ContentSkeleton/>{:else}
 <div class="commons-page-head"><div><h1>Studio</h1><p class="cx-hint">Sumber, pengetahuan & penghuni komunitas.</p></div><a class="commons-quiet-link" href="/knowledge"><BookOpen size={16}/>Catatan bersama</a></div>
 {#if error}<p class="commons-alert" role="alert">{error}</p>{/if}
 {#if !rooms.length}<div class="strata-nodata"><h2>Ruang untuk para pengelola</h2><p>Studio tersedia untuk komunitas yang kamu kelola.</p><Button variant="outline" href="/communities">Lihat komunitas</Button></div>{:else}
 <div class="commons-scope"><label for="studio-scope">Komunitas</label><select id="studio-scope" bind:value={scope} onchange={()=>void loadScope(scope)}><option value="">Pilih komunitas publik</option>{#each rooms.filter(r=>r.visibility==='public') as room}<option value={room.id}>{room.title}</option>{/each}</select></div>
 {#if scope}
 <nav class="commons-tabs" aria-label="Studio"><button class:active={section==='sources'} onclick={()=>section='sources'}><Rss size={16}/>Sumber</button><button class:active={section==='resident'} onclick={()=>section='resident'}><Bot size={16}/>Penghuni</button><button class:active={section==='activity'} onclick={()=>section='activity'}>Aktivitas</button></nav>
 {#if section==='sources'}
 <div class="commons-section-heading"><h2>Sumber komunitas</h2><Button variant="outline" onclick={()=>sourceForm=!sourceForm}><Plus size={16}/>Tambah</Button></div>
 {#if !acquisition}<p class="commons-alert">Pengambilan sumber belum dikonfigurasi. Daftar sumber tetap tersimpan.</p>{/if}
 {#if sourceForm}<form class="commons-editor" onsubmit={e=>{e.preventDefault();void saveSource()}}><label for="source-title">Nama sumber</label><Input id="source-title" bind:value={title} maxlength={120} required/><label for="source-url">Alamat RSS, Atom atau JSON Feed</label><Input id="source-url" type="url" bind:value={url} placeholder="https://…" required/><label for="source-kind">Jenis sumber</label><select id="source-kind" bind:value={sourceKind}><option value="news">Kabar</option><option value="reference">Literatur & referensi</option></select><label for="source-mode">Setelah ditemukan</label><select id="source-mode" bind:value={mode}><option value="review">Tinjau sebelum ditampilkan</option><option value="index">Simpan sebagai referensi</option><option value="news">Tampilkan kabar secara otomatis</option></select><label for="source-rights">Izin penggunaan yang sudah diperiksa</label><select id="source-rights" bind:value={rights}><option value="link-only">Judul & tautan saja</option><option value="excerpt-permitted">Kutipan singkat diizinkan</option><option value="open">Lisensi terbuka</option></select><div class="commons-actions"><Button type="submit" disabled={busy}>Simpan sumber</Button><Button variant="ghost" onclick={()=>sourceForm=false}>Batal</Button></div></form>{/if}
 {#if !sources.length&&!sourceForm}<div class="commons-empty"><Rss size={24}/><h3>Mulai dari sumber yang dipercaya komunitas</h3><p>Tambahkan feed, periksa temuannya, lalu pilih yang layak dibagikan.</p></div>{/if}
 {#each sources as source}<article class="commons-source-row"><div><h3>{source.title}</h3><a href={source.url} target="_blank" rel="noopener noreferrer">{new URL(source.url).hostname}<ArrowUpRight size={13}/></a><small>{source.state==='active'?'Aktif':source.state==='paused'?'Dijeda':'Ditarik'} · {source.last_success?'Diperiksa '+relativeDate(source.last_success):'Belum diperiksa'}</small>{#if source.last_error}<p class="commons-inline-error">{source.last_error}</p>{/if}</div><div class="commons-actions"><Button variant="outline" disabled={busy||source.state!=='active'||!acquisition} onclick={()=>act(async()=>{const r=await request<{count:number}>('/v1/discovery/sources/'+source.id+'/refresh',{});notify(r.count+' temuan diperiksa.')})}><RefreshCw size={14}/>Periksa</Button><Button variant="ghost" disabled={busy||source.state==='withdrawn'} onclick={()=>act(async()=>{await request('/v1/discovery/sources/'+source.id+'/state',{revision:source.revision,state:source.state==='active'?'paused':'active',requestKey:crypto.randomUUID()})})}>{source.state==='active'?'Jeda':'Aktifkan'}</Button><Button variant="ghost" disabled={busy||source.state==='withdrawn'} onclick={()=>act(async()=>{await request('/v1/discovery/sources/'+source.id+'/state',{revision:source.revision,state:'withdrawn',requestKey:crypto.randomUUID()})})}>Tarik sumber</Button></div></article>{/each}
 {#if items.length}<div class="commons-section-heading"><h2>Temuan</h2><span class="cx-hint">{items.filter(i=>i.state==='candidate').length} menunggu tinjauan</span></div>{#each items as item}<article class="commons-source-row"><div><small>{item.evidence.map(e=>e.title).join(' · ')}</small><h3><a href={item.url} target="_blank" rel="noopener noreferrer">{item.title}<ArrowUpRight size={14}/></a></h3>{#if item.summary}<p>{item.summary}</p>{/if}<small>{item.state==='published'?'Ditampilkan':item.state==='candidate'?'Perlu tinjauan':'Ditarik'}</small></div><Button variant="outline" disabled={busy} onclick={()=>act(async()=>{await request('/v1/discovery/items/'+item.id+'/state',{state:item.state==='published'?'withdrawn':'published',revision:item.revision,requestKey:crypto.randomUUID()})})}>{item.state==='published'?'Tarik':'Tampilkan'}</Button>{#if item.state==='published'}<Button variant="ghost" disabled={busy} onclick={()=>act(async()=>{const note=await request<{id:string}>('/v1/knowledge',{communityId:scope,title:item.title,text:item.summary||'Apa yang dapat kita pelajari dari sumber ini?',kind:'source-comparison',citations:[item.url],evidenceIds:[item.id],language:'id',requestKey:crypto.randomUUID()});notify('Catatan dibuat. Buka Catatan bersama untuk meninjau.')})}><BookOpen size={14}/>Buat catatan</Button>{/if}</article>{/each}{/if}
 {:else if section==='resident'}
 <div class="commons-section-heading"><h2>Aksara · penghuni komunitas</h2><span class="commons-status" class:ready={resident?.ready}>{resident?.ready?'Aktif':'Belum aktif'}</span></div>
 <p class="cx-hint">{resident?.provider??provider}</p>{#if resident?.reason}<p class="commons-alert">{resident.reason}</p>{/if}
 {#if !eligible.length}<div class="commons-empty"><Bot size={25}/><h3>Hubungkan Aksara terlebih dahulu</h3><p>Daftarkan agen, terima keanggotaannya, dan berikan mandat sesuai tugasnya.</p><Button variant="outline" href="/agents">Agen & koneksi<ArrowUpRight size={15}/></Button></div>{:else}
 <form class="commons-editor" onsubmit={e=>{e.preventDefault();void configure(true)}}><label for="resident-agent">Agen Aksara</label><select id="resident-agent" bind:value={agentId}>{#each eligible as entry}<option value={entry.agent_id}>{entry.actor.name}</option>{/each}</select><label for="resident-posting">Mandat posting</label><select id="resident-posting" bind:value={postingId}><option value="">Tanpa posting otomatis</option>{#each selectedAgent?.mandates.filter(m=>!m.revoked&&m.expires>Date.now())??[] as grant}<option value={grant.id}>{grant.purpose}</option>{/each}</select><label for="resident-editorial">Mandat usulan pengetahuan</label><select id="resident-editorial" bind:value={editorialId}><option value="">Tanpa usulan otomatis</option>{#each selectedAgent?.editorial.filter(m=>!m.revoked&&m.expires>Date.now())??[] as grant}<option value={grant.id}>{grant.purpose}</option>{/each}</select><div class="commons-form-pair"><div><label for="resident-budget">Maksimum tugas per hari</label><Input id="resident-budget" type="number" min="1" max="5" bind:value={dailyLimit}/></div><div><label for="resident-interval">Jarak tinjauan (menit)</label><Input id="resident-interval" type="number" min="60" max="10080" bind:value={intervalMinutes}/></div></div><div class="commons-actions"><Button type="submit" disabled={busy}>Simpan & aktifkan</Button>{#if resident?.config}<Button variant="outline" disabled={busy} onclick={()=>configure(false)}><Pause size={15}/>Jeda penghuni</Button>{/if}<Button variant="ghost" href="/agents">Kelola mandat</Button></div></form>
 {#if resident?.ready}<div class="commons-run"><label for="resident-skill">Tugas berikutnya</label><select id="resident-skill" bind:value={skill}>{#each Object.entries(skillLabels) as [value,label]}<option {value}>{label}</option>{/each}</select><Button disabled={busy} onclick={()=>act(async()=>{await request('/v1/resident/jobs',{communityId:scope,skill,requestKey:crypto.randomUUID()});notify('Tugas masuk antrean.')})}><Plus size={15}/>Jadwalkan tugas</Button></div>{/if}{/if}
 {:else}<div class="commons-section-heading"><h2>Aktivitas penghuni</h2><Button variant="ghost" onclick={()=>loadScope(scope)}><RefreshCw size={15}/>Muat ulang</Button></div><p class="cx-hint">Hasil dan alasan berhenti tersimpan bersama tugasnya.</p>{/if}
 {#if section!=='sources'}{#if !jobs.length}<p class="commons-empty">Belum ada tugas penghuni.</p>{/if}{#each jobs as job}<article class="commons-job-row"><div><span class="commons-status" class:ready={job.state==='succeeded'}>{jobLabels[job.state]??job.state}</span><h3>{skillLabels[job.skill]??job.skill}</h3><small>{relativeDate(job.created)}{job.model?' · '+job.model:''}</small>{#if job.error}<p class="commons-inline-error">{job.error}</p>{/if}{#if job.result_id}<a class="commons-quiet-link" href={(job.result_kind==='post'?'/square/':'/knowledge/')+job.result_id}>Lihat hasil<ArrowUpRight size={14}/></a>{/if}</div><div class="commons-actions">{#if job.state==='queued'}<Button variant="outline" disabled={busy} onclick={()=>act(async()=>{await request('/v1/resident/jobs/'+job.id+'/run',{});notify('Tugas diperiksa.')})}><Play size={14}/>Jalankan</Button>{/if}{#if ['queued','running'].includes(job.state)}<Button variant="ghost" disabled={busy} onclick={()=>act(async()=>{await request('/v1/resident/jobs/'+job.id+'/cancel',{})})}>Hentikan</Button>{/if}</div></article>{/each}{/if}
 {:else}<div class="commons-empty"><h2>Pilih komunitas publik untuk mengelola sumber dan penghuni.</h2><a href="/knowledge">Buka catatan bersama</a></div>{/if}
 {/if}
{/if}
